css:
.tile-img{position:absolute;inset:4px;width:calc(100% - 8px);height:calc(100% - 8px);border-radius:12px;box-shadow:0 2px 6px rgba(0,0,0,.25)}
#ms{background:#173525}
#ms .topbar{background:#1b3f2a;gap:4px}
.ms-hud{flex:1;display:flex;justify-content:center;gap:18px;font-size:17px;font-variant-numeric:tabular-nums}
.ms-mode.on{background:rgba(229,52,74,.3)}
#msWrap{position:relative;flex:1;overflow:hidden;touch-action:none;user-select:none;-webkit-user-select:none}
#msCanvas{position:absolute;left:0;top:0;display:block}
.ms-levels{display:grid;gap:8px;margin:10px 0}
.ms-levels button{display:grid;grid-template-columns:1fr auto;grid-template-rows:auto auto;text-align:left;background:rgba(0,0,0,.25);border:2px solid transparent;border-radius:14px;padding:10px 14px;color:var(--ink)}
.ms-levels button b{font-size:17px} .ms-levels button small{color:var(--muted);grid-column:1} .ms-levels button span{grid-column:2;grid-row:1/3;align-self:center;font-variant-numeric:tabular-nums;color:var(--muted)}
.ms-levels button.on{border-color:var(--accent);background:rgba(242,193,78,.15)}

