/* ================================================================
   MIJNENVEGER – classic minesweeper in a garden: safe first tap,
   long-press or flag mode to mark, chording, pinch-zoom for big boards
   ================================================================ */
const Mines = (() => {
  const LEVELS = { makkelijk: { r: 9, c: 9, m: 10, name: 'Makkelijk' }, normaal: { r: 16, c: 16, m: 40, name: 'Normaal' }, moeilijk: { r: 30, c: 16, m: 99, name: 'Moeilijk' } };
  const D = { level: 'makkelijk', sound: true, flagMode: false };
  const opt = Object.assign({}, D, store.get('ms.settings', {}));
  const saveOpt = () => store.set('ms.settings', opt);
  let stats = Object.assign({ played: 0, won: 0, best: {}, streak: 0 }, store.get('ms.stats', {}));
  const saveStats = () => store.set('ms.stats', stats);
  Sfx.gate('ms', () => opt.sound);
  const sfx = (n, a, p) => { if (opt.sound) Sfx.play(n, a, p); };
  const wrap = $('#msWrap'), cv = $('#msCanvas'), ctx = cv.getContext('2d');
  let S = null, W = 0, H = 0, dpr = 1, raf = 0, running = false, dirty = true;
  let view = { s: 1, x: 0, y: 0, fit: 1 }, anim = new Map(), booms = [], confetti = [], timerT = 0;

  /* ---------- game state ---------- */
  function newGame(lvl) {
    const L = LEVELS[lvl || opt.level]; opt.level = lvl || opt.level; saveOpt();
    S = { lvl: opt.level, rows: L.r, cols: L.c, mines: L.m, mine: Array(L.r * L.c).fill(0), adj: Array(L.r * L.c).fill(0), st: Array(L.r * L.c).fill(0), first: true, over: false, won: false, time: 0, counted: false, lost: -1 };
    anim.clear(); booms = []; confetti = []; layout(true); hud(); save(); dirty = true; closeModals();
  }
  const idx = (r, c) => r * S.cols + c;
  const nb = i => { const r = Math.floor(i / S.cols), c = i % S.cols, o = []; for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) { if (!dr && !dc) continue; const rr = r + dr, cc = c + dc; if (rr >= 0 && cc >= 0 && rr < S.rows && cc < S.cols) o.push(idx(rr, cc)); } return o; };
