  }
  function reveal(i0) {
    if (S.over || S.st[i0] !== 0) return;
    if (S.first) { plant(i0); S.first = false; if (!S.counted) { S.counted = true; stats.played++; saveStats(); } }
    if (S.mine[i0]) return lose(i0);
    const now = performance.now(), q = [[i0, 0]], seen = new Set([i0]); let n = 0;
    while (q.length) {
      const [i, d] = q.shift(); if (S.st[i] !== 0) continue; S.st[i] = 1; n++; anim.set(i, now + d * 22);
      if (S.adj[i] === 0) for (const j of nb(i)) if (!seen.has(j) && S.st[j] === 0 && !S.mine[j]) { seen.add(j); q.push([j, d + 1]); }
    }
    sfx(n > 6 ? 'msCascade' : 'msPop', null, pan(i0)); vibrate(n > 6 ? 12 : 5);
    dirty = true; checkWin(); save(); hud();
  }
  function chord(i) {
    if (S.st[i] !== 1 || !S.adj[i]) return;
    const ns = nb(i), flags = ns.filter(j => S.st[j] === 2).length;
    if (flags !== S.adj[i]) { for (const j of ns) if (S.st[j] === 0) anim.set(-1 - j, performance.now()); dirty = true; return; }
    const hit = ns.find(j => S.st[j] === 0 && S.mine[j]); if (hit != null) return lose(hit);
    for (const j of ns) if (S.st[j] === 0) reveal(j);
  }
  function flag(i) {
    if (S.over || S.st[i] === 1) return;
    S.st[i] = S.st[i] === 2 ? 0 : 2; anim.set(i, performance.now()); sfx(S.st[i] === 2 ? 'msFlag' : 'msUnflag', null, pan(i)); vibrate(20); dirty = true; hud(); save();
  }
  function lose(i) {
    S.over = true; S.lost = i; stats.streak = 0; saveStats(); store.del('ms.save');
    const now = performance.now(); booms.push({ i, t: now }); sfx('boom'); vibrate(120);
    const rest = []; for (let j = 0; j < S.mine.length; j++) if (S.mine[j] && j !== i && S.st[j] !== 2) rest.push(j);
    const r0 = Math.floor(i / S.cols), c0 = i % S.cols;
    rest.sort((a, b) => Math.hypot(Math.floor(a / S.cols) - r0, a % S.cols - c0) - Math.hypot(Math.floor(b / S.cols) - r0, b % S.cols - c0));
    rest.forEach((j, k) => { const t = now + 250 + k * 70; booms.push({ i: j, t }); if (k < 12) setTimeout(() => sfx('pop'), 250 + k * 70); });
    dirty = true; hud();
    setTimeout(() => showEnd(false), 1300 + Math.min(rest.length, 20) * 70);
  }
  function checkWin() {
    const closed = S.st.reduce((a, v, i) => a + (v !== 1 ? 1 : 0), 0);
    if (closed !== S.mines) return;
    S.over = true; S.won = true; for (let i = 0; i < S.mine.length; i++) if (S.mine[i]) S.st[i] = 2;
    stats.won++; stats.streak++; const t = Math.floor(S.time); const prev = stats.best[S.lvl]; S.newBest = prev == null || t < prev; if (S.newBest) stats.best[S.lvl] = t; saveStats(); store.del('ms.save');
    sfx('pfWin'); vibrate(60);
    for (let k = 0; k < 90; k++) confetti.push({ x: W * Math.random(), y: -20 - Math.random() * H * .3, vx: (Math.random() - .5) * 80, vy: 80 + Math.random() * 160, r: Math.random() * 6, vr: (Math.random() - .5) * 8, c: ['#ffd23f', '#e5344a', '#3d9bff', '#2fb36a', '#ffffff'][k % 5], t: performance.now() });
