  }
  const pan = i => { const c = i % S.cols; return ((c + .5) / S.cols - .5) * .8; };
  function save() { if (S && !S.over && !S.first) store.set('ms.save', S); }
  const flagsLeft = () => S ? S.mines - S.st.filter(v => v === 2).length : 0;
  const fmt = t => `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, '0')}`;
  function hud() { $('#msLeft').textContent = flagsLeft(); $('#msTime').textContent = fmt(S ? S.time : 0); $('#msFlag').classList.toggle('on', opt.flagMode); $('#msFlag').textContent = opt.flagMode ? '🚩' : '⛏'; }

  /* ---------- layout / view ---------- */
  function layout(reset) {
    dpr = window.devicePixelRatio || 1; W = wrap.clientWidth; H = wrap.clientHeight;
    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr); cv.style.width = W + 'px'; cv.style.height = H + 'px';
    if (!S) return;
    const pad = 10, fit = Math.min((W - pad * 2) / S.cols, (H - pad * 2) / S.rows);
    view.fit = fit;
    if (reset || view.s < fit) { view.s = fit; }
