  }

  /* ---------- drawing ---------- */
  let spriteKey = '', SP = {};
  const NUMC = ['', '#2a6fd1', '#2e8b3c', '#d33a2f', '#6b3fa0', '#b8572a', '#1b8a8a', '#3a3a3a', '#7a7a7a'];
  function sprites() {
    const cs = Math.max(8, Math.round(view.s * dpr)), key = cs + '';
    if (key === spriteKey) return cs; spriteKey = key; SP = {};
    const mk = (fn) => { const c = document.createElement('canvas'); c.width = c.height = cs; const g = c.getContext('2d'); g.scale(cs / 100, cs / 100); g.lineJoin = g.lineCap = 'round'; fn(g); return c; };
    for (const v of [0, 1]) {
      SP['c' + v] = mk(g => {
        let q = g.createLinearGradient(0, 0, 0, 100); q.addColorStop(0, v ? '#9bd65a' : '#a9dd66'); q.addColorStop(1, v ? '#7dbf3f' : '#88c847'); g.fillStyle = q; g.fillRect(0, 0, 100, 100);
        g.fillStyle = 'rgba(255,255,255,.22)'; g.fillRect(0, 0, 100, 5); g.fillStyle = 'rgba(40,80,10,.22)'; g.fillRect(0, 93, 100, 7);
        g.strokeStyle = 'rgba(60,120,20,.35)'; g.lineWidth = 2.2; for (const [x, y] of [[22, 30], [64, 22], [40, 66], [78, 70], [15, 80]]) { g.beginPath(); g.moveTo(x, y + 9); g.quadraticCurveTo(x + 2, y + 3, x + 5, y); g.moveTo(x + 4, y + 9); g.quadraticCurveTo(x + 6, y + 4, x + 9, y + 2); g.stroke(); }
      });
      SP['o' + v] = mk(g => { g.fillStyle = v ? '#e3c9a0' : '#ecd5ae'; g.fillRect(0, 0, 100, 100); g.fillStyle = 'rgba(120,80,40,.08)'; for (const [x, y, r] of [[25, 30, 4], [70, 60, 3], [45, 80, 2.5], [80, 20, 2]]) { g.beginPath(); g.arc(x, y, r, 0, 7); g.fill(); } });
    }
    for (let n = 1; n <= 8; n++) SP['n' + n] = mk(g => { g.font = '900 64px system-ui,Roboto,sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillStyle = 'rgba(0,0,0,.12)'; g.fillText(n, 52, 56); g.fillStyle = NUMC[n]; g.fillText(n, 50, 53); });
    SP.flag = mk(g => {
      g.fillStyle = 'rgba(0,0,0,.25)'; g.beginPath(); g.ellipse(52, 82, 20, 6, 0, 0, 7); g.fill();
      g.fillStyle = '#5a3b20'; g.fillRect(40, 18, 6, 64);
      g.beginPath(); g.moveTo(46, 18); g.quadraticCurveTo(62, 22, 78, 26); g.quadraticCurveTo(66, 34, 74, 46); g.quadraticCurveTo(58, 44, 46, 50); g.closePath();
      let q = g.createLinearGradient(46, 18, 78, 46); q.addColorStop(0, '#ff6b5a'); q.addColorStop(1, '#c91f1f'); g.fillStyle = q; g.fill(); g.strokeStyle = '#7a1010'; g.lineWidth = 2; g.stroke();
      g.fillStyle = '#e8e2d4'; g.beginPath(); g.ellipse(43, 82, 14, 5, 0, 0, 7); g.fill();
    });
    SP.mine = mk(g => {
      g.strokeStyle = '#23262c'; g.lineWidth = 7; for (let k = 0; k < 8; k++) { const a = k * Math.PI / 4; g.beginPath(); g.moveTo(50 + Math.cos(a) * 18, 52 + Math.sin(a) * 18); g.lineTo(50 + Math.cos(a) * 33, 52 + Math.sin(a) * 33); g.stroke(); }
      const q = g.createRadialGradient(42, 44, 3, 50, 52, 26); q.addColorStop(0, '#6b7280'); q.addColorStop(1, '#16181c'); g.fillStyle = q; g.beginPath(); g.arc(50, 52, 24, 0, 7); g.fill();
      g.fillStyle = 'rgba(255,255,255,.65)'; g.beginPath(); g.ellipse(41, 43, 7, 4.5, -.6, 0, 7); g.fill();
    });
    SP.x = mk(g => { g.strokeStyle = '#d33'; g.lineWidth = 9; g.beginPath(); g.moveTo(20, 20); g.lineTo(80, 80); g.moveTo(80, 20); g.lineTo(20, 80); g.stroke(); });
    return cs;
  }
  function draw(now) {
    if (!S) return;
    sprites();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    let q = ctx.createLinearGradient(0, 0, 0, cv.height); q.addColorStop(0, '#2c5a3a'); q.addColorStop(1, '#173525'); ctx.fillStyle = q; ctx.fillRect(0, 0, cv.width, cv.height);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.imageSmoothingEnabled = true;
    const s = view.s, ox = view.x, oy = view.y;
    // board frame
    ctx.save(); ctx.shadowColor = 'rgba(0,0,0,.45)'; ctx.shadowBlur = 18; ctx.shadowOffsetY = 6; ctx.fillStyle = '#5b3d22'; ctx.beginPath(); ctx.roundRect ? ctx.roundRect(ox - 6, oy - 6, S.cols * s + 12, S.rows * s + 12, 10) : ctx.rect(ox - 6, oy - 6, S.cols * s + 12, S.rows * s + 12); ctx.fill(); ctx.restore();
    const c0 = Math.max(0, Math.floor(-ox / s)), c1 = Math.min(S.cols - 1, Math.ceil((W - ox) / s)), r0 = Math.max(0, Math.floor(-oy / s)), r1 = Math.min(S.rows - 1, Math.ceil((H - oy) / s));
    let animating = false;
    for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) {
      const i = idx(r, c), x = ox + c * s, y = oy + r * s, v = (r + c) & 1, st = S.st[i];
      ctx.drawImage(SP['o' + v], x, y, s + .5, s + .5);
      if (st === 1) {
        const a0 = anim.get(i); let k = 1; if (a0 != null) { k = Math.min(1, Math.max(0, (now - a0) / 160)); if (k < 1) animating = true; else anim.delete(i); }
        if (S.adj[i] && !S.mine[i]) { ctx.globalAlpha = k; ctx.drawImage(SP['n' + S.adj[i]], x, y, s, s); ctx.globalAlpha = 1; }
        if (k < 1) { const sc = 1 - k; ctx.globalAlpha = sc; ctx.drawImage(SP['c' + v], x + s * (1 - sc) / 2, y + s * (1 - sc) / 2, s * sc, s * sc); ctx.globalAlpha = 1; }
        continue;
      }
      // closed (or flagged) grass tile with a soft shadow onto open neighbours
      const pr = anim.get(-1 - i); let dy = 0; if (pr != null) { const k = (now - pr) / 220; if (k < 1) { dy = Math.sin(k * Math.PI) * s * .08; animating = true; } else anim.delete(-1 - i); }
      ctx.drawImage(SP['c' + v], x, y + dy, s + .5, s + .5);
      if (st === 2) {
        const a0 = anim.get(i); let k = 1; if (a0 != null) { k = Math.min(1, (now - a0) / 180); if (k < 1) animating = true; else anim.delete(i); }
