    for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) { const i = idx(r, c); if (S.st[i] !== 1) continue; if (r > 0 && S.st[i - S.cols] !== 1) ctx.fillRect(ox + c * s, oy + r * s, s, s * .1); if (c > 0 && S.st[i - 1] !== 1) ctx.fillRect(ox + c * s, oy + r * s, s * .08, s); }
