    clearTimeout(lpTimer); lpTimer = setTimeout(() => { if (press && !press.moved && press.i != null && !S.over) { press.long = true; if (S.st[press.i] === 1) chord(press.i); else flag(press.i); press.i = null; } }, 380);
  });
