    if (!pointers.has(e.pointerId)) return; const p = pos(e); pointers.set(e.pointerId, p);
    if (pinch && pointers.size >= 2) {
      const [a, b] = [...pointers.values()], d = Math.hypot(a.x - b.x, a.y - b.y), cx = (a.x + b.x) / 2, cy = (a.y + b.y) / 2;
      const ns = Math.max(view.fit, Math.min(maxS(), pinch.s * d / pinch.d));
      view.x = cx - (pinch.cx - pinch.vx) * ns / pinch.s; view.y = cy - (pinch.cy - pinch.vy) * ns / pinch.s; view.s = ns; clampView(false); dirty = true; return;
    }
    if (press && Math.hypot(p.x - press.x, p.y - press.y) > 10) {
      press.moved = true; clearTimeout(lpTimer);
      if (view.s > view.fit + .01) { view.x = press.vx + p.x - press.x; view.y = press.vy + p.y - press.y; clampView(false); }
      dirty = true;
    }
  });
  const up = e => {
    if (!pointers.has(e.pointerId)) return; pointers.delete(e.pointerId);
    if (pinch) { if (pointers.size < 2) { pinch = null; spriteKey = ''; dirty = true; } return; }
    clearTimeout(lpTimer);
    if (press && !press.moved && !press.long && press.i != null && e.type === 'pointerup' && !S.over) {
      const i = press.i;
      if (S.st[i] === 1) chord(i); else if (opt.flagMode) flag(i); else if (S.st[i] === 0) reveal(i);
    }
    press = null; dirty = true;
  };
  cv.addEventListener('pointerup', up); cv.addEventListener('pointercancel', up);
  cv.addEventListener('wheel', e => { if (!S) return; e.preventDefault(); const p = pos(e), ns = Math.max(view.fit, Math.min(maxS(), view.s * (e.deltaY < 0 ? 1.15 : 1 / 1.15))); view.x = p.x - (p.x - view.x) * ns / view.s; view.y = p.y - (p.y - view.y) * ns / view.s; view.s = ns; clampView(false); spriteKey = ''; dirty = true; }, { passive: false });
